mapper.insert:
INSERT /* SQL_ID: CountryCodeMapper.insertCountryCode */
       INTO dtmeta.tb_portal_countrycode
	 ( cntry_cd
	 , cntry_nm
	 , cntry_eng_nm
	 , cntry_numb
	 , cntry_alpha3
	 , cntry_alpha2
	 , cntry_data_sttus_mtcd
	 , cntry_regr_id
	 , cntry_regr_nm
	 , cntry_reg_dt
	 , cntry_amdr_id
	 , cntry_amdr_nm
	 , cntry_amd_dt

	 ) VALUES 
	 ( 
	   #{cntryCd}
	 , #{cntryNm}
	 , #{cntryEngNm}
	 , #{cntryNumb}
	 , #{cntryAlpha3}
	 , #{cntryAlpha2}
	 , #{cntryDataSttusMtcd}
	 , #{cntryRegrId}
	 , #{cntryRegrNm}
	 , current_timestamp
	 , #{cntryAmdrId}
	 , #{cntryAmdrNm}
	 , current_timestamp
	 )

mapper.update:
		UPDATE /* SQL_ID: CountryCodeMapper.updateCountryCode */
               dtmeta.tb_portal_countrycode
		   SET cntry_nm					= #{cntryNm}
             , cntry_eng_nm				= #{cntryEngNm}
             , cntry_numb				= #{cntryNumb}
             , cntry_alpha3				= #{cntryAlpha3}
             , cntry_alpha2				= #{cntryAlpha2}
             , cntry_data_sttus_mtcd	= #{cntryDataSttusMtcd}
             , cntry_amdr_id			= #{cntryAmdrId}
             , cntry_amdr_nm			= #{cntryAmdrNm}
             , cntry_amd_dt				= current_timestamp            
		 WHERE cntry_cd 	      = #{cntryCd}

mapper.select:
SELECT EXISTS (  /* SQL_ID: CountryCodeMapper.isDuplicatedCountryCode */
	SELECT 1
	FROM dtmeta.tb_portal_countrycode
	WHERE cntry_cd = #{cntryCd}
)
